// WithRuntime option sets a container runtime to be used by containerlab.
func WithRuntime(name string, rtconfig *clabruntime.RuntimeConfig) ClabOption {
	return func(c *CLab) error {
		name = resolveRuntimeName(name)

		if clablabruntime.IsLabRuntimeName(name) {
			c.globalRuntimeName = name

			lr, err := clablabruntime.Init(name, clablabruntime.Config{
				Timeout:   runtimeTimeout(rtconfig),
				Namespace: labRuntimeNamespace(rtconfig),
				// The kind registry is populated before options run; lab runtimes use it to
				// predict the lifecycle impact of link changes in their plan.
				KindLinkApplyMode: func(kind string) string {
					return string(c.Reg.LinkApplyModeForKind(kind))
				},
			})
			if err != nil {
				return fmt.Errorf("failed to init the lab runtime: %w", err)
			}

			c.LabRuntime = lr

			return nil
		}

		name, rInit, err := RuntimeInitializer(name)
		if err != nil {
			return err
		}
		c.globalRuntimeName = name

		r := rInit()

		log.Debugf("Running runtime.Init with params %+v and %+v", rtconfig, c.Config.Mgmt)

		err = r.Init(
			clabruntime.WithConfig(rtconfig),
			clabruntime.WithMgmtNet(c.Config.Mgmt),
		)
		if err != nil {
			return fmt.Errorf("failed to init the container runtime: %v", err)
		}

		c.Runtimes[name] = r

		log.Debugf("initialized a runtime with params %+v", r)

		return nil
	}
}

